window.__ModuleLoader__.load({
  id: '@local/quota-whale',
  factory(require) {
    const React = require('react');
    const h = React.createElement;

    const REFRESH_INTERVAL_MS = 120000;
    const BOOT = (typeof globalThis !== 'undefined' && globalThis.__DSH_BOOT__) || {};
    const CLIENT_VERSION = BOOT && BOOT.release && typeof BOOT.release.version === 'string'
      ? BOOT.release.version
      : '1.0.0';
    const WIDGET_SIZE = 240;
    const VIEWPORT_MARGIN = 8;
    const POSITION_KEY = 'dsh.quota-whale.position.v1';
    const SCALE_KEY = 'dsh.quota-whale.scale.v1';
    const MIN_SCALE = 0.6;
    const MAX_SCALE = 2;

    const PHRASES = {
      zh: [
        '欧鲸鲸',
        '想吃饭',
        '我去吃饭了',
        '吃什么呢？',
        '不许叫大肥鱼！',
        '鱼片，贴贴',
        '好困，想睡',
        '白米饭最香了',
        '摸鱼一下下',
        '才不胖呢',
        '今天也要好好干活',
        '给我一碗白饭',
      ],
      en: [
        'Oh whale~',
        'Hungry...',
        'Time to eat!',
        'What should I eat?',
        "Don't call me big fish!",
        'Fish flakes, head pats',
        'Sleepy...',
        'White rice is the best',
        'Tiny break~',
        "I'm not chubby!",
        'Work hard today too',
        'One bowl of rice, please',
      ],
    };

    const FAVORITE_PHRASES = new Set(['欧鲸鲸', 'Oh whale~']);
    const PHRASE_WEIGHT = 11;

    const MASCOT_URI = 'data:image/png;base64,';

    const MESSAGES = {
      zh: {
        label: '剩余额度',
        loading: '正在查询…',
        signedOut: '未登录',
        signInHint: '登录账号后显示额度',
        unavailable: '暂不可用',
        retry: '点击重试',
        bonusLabel: '赠金',
        updated: '点击刷新',
        refresh: '点击刷新额度',
        dragHint: '拖动改变位置，点击刷新额度',
      },
      en: {
        label: 'Remaining',
        loading: 'Checking…',
        signedOut: 'Signed out',
        signInHint: 'Sign in to see your balance',
        unavailable: 'Unavailable',
        retry: 'Click to retry',
        bonusLabel: 'Bonus',
        updated: 'Click to refresh',
        refresh: 'Refresh balance',
        dragHint: 'Drag to move, click to refresh',
      },
    };

    const CSS = `
      .qw-root {
        position: fixed;
        left: 0;
        top: 0;
        z-index: 30;
        width: 240px;
        height: 240px;
        pointer-events: none;
        font-family: inherit;
        user-select: none;
        touch-action: none;
        will-change: transform;
      }
      .qw-scale {
        width: 100%;
        height: 100%;
        transform-origin: top left;
      }
      .qw-sticker {
        position: relative;
        width: 100%;
        height: 100%;
        transform-origin: 62% 92%;
        animation: qw-float 4.4s ease-in-out infinite;
      }
      .qw-pop {
        position: relative;
        width: 100%;
        height: 100%;
        transform-origin: 60% 88%;
      }
      .qw-pop[data-pop="true"] {
        animation: qw-pop .58s cubic-bezier(.22, .9, .3, 1);
      }
      .qw-art {
        display: block;
        width: 100%;
        height: 100%;
        object-fit: contain;
        pointer-events: none;
        user-select: none;
        -webkit-user-drag: none;
        filter: drop-shadow(0 9px 16px rgba(20, 40, 80, .18));
      }
      .qw-bubble {
        position: absolute;
        left: 8%;
        top: 8%;
        width: 50%;
        height: 33%;
        margin: 0;
        padding: 0;
        border: 0;
        border-radius: 50%;
        background: transparent;
        color: #1e3768;
        cursor: grab;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 0;
        font: inherit;
        text-align: center;
        pointer-events: auto;
        touch-action: none;
        z-index: 2;
      }
      .qw-bubble:hover .qw-amount { color: #2f5da8; }
      .qw-bubble:focus-visible {
        outline: 2px solid #4267a8;
        outline-offset: 1px;
      }
      .qw-label {
        color: #5a7099;
        font-size: 10.5px;
        font-weight: 600;
        letter-spacing: .08em;
        line-height: 1.2;
      }
      .qw-amount {
        color: #1e3768;
        font-size: 21px;
        font-weight: 700;
        line-height: 1.16;
        font-variant-numeric: tabular-nums;
        white-space: nowrap;
        transition: color .18s ease, opacity .18s ease;
      }
      .qw-root[data-refreshing="true"] .qw-amount { opacity: .55; }
      .qw-sub {
        color: #6b7f9f;
        font-size: 9.5px;
        line-height: 1.25;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        max-width: 100%;
      }
      .qw-phrase {
        color: #1e3768;
        font-size: 14px;
        font-weight: 700;
        line-height: 1.25;
        text-align: center;
        max-width: 100%;
        padding: 0 6px;
        word-break: break-word;
        animation: qw-phrase-in .18s ease-out;
      }
      .qw-character {
        position: absolute;
        left: 40%;
        top: 28%;
        width: 58%;
        height: 70%;
        margin: 0;
        padding: 0;
        border: 0;
        border-radius: 46%;
        background: transparent;
        cursor: grab;
        pointer-events: auto;
        touch-action: none;
        z-index: 1;
      }
      .qw-character:focus-visible {
        outline: 2px solid #4267a8;
        outline-offset: -6px;
      }
      .qw-root[data-dragging="true"] .qw-bubble,
      .qw-root[data-dragging="true"] .qw-character {
        cursor: grabbing;
      }
      .qw-root[data-dragging="true"] .qw-sticker {
        animation-play-state: paused;
      }
      @keyframes qw-float {
        0%, 100% { transform: translateY(0); }
        50% { transform: translateY(-4px); }
      }
      @keyframes qw-pop {
        0% { transform: scale(1); }
        20% { transform: scale(1.14, .84); }
        40% { transform: scale(.9, 1.12); }
        60% { transform: scale(1.06, .94); }
        78% { transform: scale(.97, 1.03); }
        100% { transform: scale(1); }
      }
      @keyframes qw-phrase-in {
        from { opacity: 0; transform: scale(.9); }
        to { opacity: 1; transform: scale(1); }
      }
      @media (prefers-reduced-motion: reduce) {
        .qw-sticker { animation: none; }
        .qw-pop[data-pop="true"] { animation: none; }
        .qw-phrase { animation: none; }
        .qw-amount { transition: none; }
      }
    `;

    function viewport() {
      const width = typeof window !== 'undefined' && Number.isFinite(window.innerWidth) ? window.innerWidth : 1280;
      const height = typeof window !== 'undefined' && Number.isFinite(window.innerHeight) ? window.innerHeight : 800;
      return { width, height };
    }

    function clampScale(value) {
      return Math.min(MAX_SCALE, Math.max(MIN_SCALE, value));
    }

    function initialScale() {
      try {
        const raw = window.localStorage.getItem(SCALE_KEY);
        if (raw !== null && raw !== '') {
          const saved = Number(raw);
          if (Number.isFinite(saved)) return clampScale(saved);
        }
      } catch (error) {
        // Browser storage may be unavailable; the default remains usable.
      }
      return 1;
    }

    function languageOf(locale) {
      try {
        if (locale && typeof locale.getSnapshot === 'function') {
          const active = locale.getSnapshot().active;
          if (active && String(active).toLowerCase().startsWith('zh')) return 'zh';
        }
      } catch (error) {
        // Fall back to Chinese phrases.
      }
      return 'zh';
    }

    function clampPosition(x, y, scale = 1) {
      const { width, height } = viewport();
      const size = WIDGET_SIZE * scale;
      const maxX = Math.max(0, width - size - VIEWPORT_MARGIN);
      const maxY = Math.max(0, height - size - VIEWPORT_MARGIN);
      const minX = Math.min(VIEWPORT_MARGIN, maxX);
      const minY = Math.min(VIEWPORT_MARGIN, maxY);
      return {
        x: Math.min(Math.max(minX, x), maxX),
        y: Math.min(Math.max(minY, y), maxY),
      };
    }

    function initialPosition(scale = 1) {
      const { width, height } = viewport();
      const size = WIDGET_SIZE * scale;
      try {
        const raw = window.localStorage.getItem(POSITION_KEY);
        if (raw) {
          const saved = JSON.parse(raw);
          if (saved && Number.isFinite(saved.x) && Number.isFinite(saved.y)) {
            return clampPosition(saved.x, saved.y, scale);
          }
        }
      } catch (error) {
        // Browser storage may be unavailable; the default remains usable.
      }
      return clampPosition(width - size - 16, height - size - 104, scale);
    }

    function metadata(locale) {
      let active = (typeof navigator !== 'undefined' && navigator.language) || 'zh-CN';
      try {
        if (locale && typeof locale.getSnapshot === 'function') {
          const snapshot = locale.getSnapshot();
          if (snapshot && snapshot.active) active = snapshot.active;
        }
      } catch (error) {
        // Fall back to the browser language.
      }
      return {
        version: CLIENT_VERSION,
        locale: active,
        timezoneOffsetSeconds: -new Date().getTimezoneOffset() * 60,
      };
    }

    function money(balance, currency) {
      const symbol = currency === 'USD' ? '$' : '¥';
      const value = Number(balance);
      if (!Number.isFinite(value)) return symbol + String(balance ?? '');
      const magnitude = Math.abs(value);
      if (magnitude > 0 && magnitude < 0.01) return (value < 0 ? '-' : '') + symbol + '0.01';
      return (value < 0 ? '-' : '') + symbol + magnitude.toFixed(2);
    }

    function positiveWallet(wallets) {
      if (!Array.isArray(wallets)) return null;
      for (const wallet of wallets) {
        const value = Number(wallet && wallet.balance);
        if (Number.isFinite(value) && value > 0) return wallet;
      }
      return null;
    }

    function failureText(result) {
      if (!result || !result.error) return 'remote call failed';
      return [result.error.code, result.error.message].filter(Boolean).join(': ') || 'remote call failed';
    }

    function QuotaWhale(props) {
      const locale = props.locale;
      const translate = typeof props.t === 'function' ? props.t : (key) => key;
      const remote = props.remote;
      const [model, setModel] = React.useState({ status: 'loading' });
      const [, setLocaleTick] = React.useState(0);
      const requestRef = React.useRef(0);
      const mountedRef = React.useRef(true);
      const [scale, setScale] = React.useState(initialScale);
      const scaleRef = React.useRef(scale);
      const [position, setPosition] = React.useState(() => initialPosition(scale));
      const positionRef = React.useRef(position);
      const dragRef = React.useRef(null);
      const suppressClickRef = React.useRef(false);
      const [dragging, setDragging] = React.useState(false);
      const rootRef = React.useRef(null);
      const hoverRef = React.useRef(false);
      const [popping, setPopping] = React.useState(false);
      const popTimerRef = React.useRef(0);
      const [phrase, setPhrase] = React.useState(null);
      const phraseTimerRef = React.useRef(0);
      const lastPhraseRef = React.useRef('');

      const beginDrag = (event) => {
        if (event.button !== 0) return;
        suppressClickRef.current = false;
        const current = positionRef.current;
        dragRef.current = {
          pointerId: event.pointerId,
          startX: event.clientX,
          startY: event.clientY,
          originX: current.x,
          originY: current.y,
          moved: false,
        };
        try {
          event.currentTarget.setPointerCapture(event.pointerId);
        } catch (error) {
          // Pointer capture is best-effort.
        }
      };

      const moveDrag = (event) => {
        const drag = dragRef.current;
        if (!drag || drag.pointerId !== event.pointerId) return;
        const dx = event.clientX - drag.startX;
        const dy = event.clientY - drag.startY;
        if (!drag.moved && Math.hypot(dx, dy) < 4) return;
        drag.moved = true;
        setDragging(true);
        const next = clampPosition(drag.originX + dx, drag.originY + dy, scaleRef.current);
        positionRef.current = next;
        setPosition(next);
      };

      const endDrag = (event) => {
        const drag = dragRef.current;
        if (!drag || drag.pointerId !== event.pointerId) return;
        if (drag.moved) {
          suppressClickRef.current = true;
          try {
            window.localStorage.setItem(POSITION_KEY, JSON.stringify(positionRef.current));
          } catch (error) {
            // Storage is optional.
          }
        }
        dragRef.current = null;
        setDragging(false);
        try {
          event.currentTarget.releasePointerCapture(event.pointerId);
        } catch (error) {
          // Pointer capture is best-effort.
        }
      };

      const savePosition = (value) => {
        try {
          window.localStorage.setItem(POSITION_KEY, JSON.stringify(value));
        } catch (error) {
          // Storage is optional.
        }
      };

      const saveScale = (value) => {
        try {
          window.localStorage.setItem(SCALE_KEY, String(value));
        } catch (error) {
          // Storage is optional.
        }
      };

      const showPhrase = () => {
        const list = PHRASES[languageOf(locale)] || PHRASES.zh;
        const weighted = [];
        for (const text of list) {
          const weight = FAVORITE_PHRASES.has(text) ? PHRASE_WEIGHT : 1;
          for (let i = 0; i < weight; i += 1) weighted.push(text);
        }
        let next = weighted[Math.floor(Math.random() * weighted.length)];
        if (next === lastPhraseRef.current && !FAVORITE_PHRASES.has(next)) {
          const alternatives = list.filter((text) => text !== next);
          next = alternatives[Math.floor(Math.random() * alternatives.length)];
        }
        lastPhraseRef.current = next;
        setPhrase(next);
        window.clearTimeout(phraseTimerRef.current);
        phraseTimerRef.current = window.setTimeout(() => {
          if (mountedRef.current) setPhrase(null);
        }, 1800);
      };

      const triggerPop = () => {
        setPopping(false);
        const frame = typeof window.requestAnimationFrame === 'function'
          ? window.requestAnimationFrame.bind(window)
          : (callback) => window.setTimeout(callback, 0);
        frame(() => {
          if (!mountedRef.current) return;
          setPopping(true);
          window.clearTimeout(popTimerRef.current);
          popTimerRef.current = window.setTimeout(() => {
            if (mountedRef.current) setPopping(false);
          }, 700);
        });
      };

      const handlePointerOver = (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) hoverRef.current = true;
      };

      const handlePointerOut = (event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) hoverRef.current = false;
      };

      React.useEffect(() => {
        const node = rootRef.current;
        if (!node) return undefined;
        const onWheel = (event) => {
          if (!hoverRef.current) return;
          event.preventDefault();
          if (!Number.isFinite(event.deltaY) || event.deltaY === 0) return;
          const factor = event.deltaY < 0 ? 1.08 : 0.92;
          const nextScale = clampScale(scaleRef.current * factor);
          if (nextScale === scaleRef.current) return;
          const nextPosition = clampPosition(positionRef.current.x, positionRef.current.y, nextScale);
          scaleRef.current = nextScale;
          positionRef.current = nextPosition;
          setScale(nextScale);
          setPosition(nextPosition);
          saveScale(nextScale);
          savePosition(nextPosition);
        };
        node.addEventListener('wheel', onWheel, { passive: false });
        return () => node.removeEventListener('wheel', onWheel);
      }, []);

      React.useEffect(() => {
        const onResize = () => {
          const next = clampPosition(positionRef.current.x, positionRef.current.y, scaleRef.current);
          positionRef.current = next;
          setPosition(next);
        };
        window.addEventListener('resize', onResize);
        return () => window.removeEventListener('resize', onResize);
      }, []);

      React.useEffect(() => {
        mountedRef.current = true;
        return () => {
          mountedRef.current = false;
          window.clearTimeout(popTimerRef.current);
          window.clearTimeout(phraseTimerRef.current);
        };
      }, []);

      React.useEffect(() => {
        if (!locale || typeof locale.subscribe !== 'function') return undefined;
        return locale.subscribe(() => setLocaleTick((value) => value + 1));
      }, [locale]);

      const load = React.useCallback(async () => {
        const seq = ++requestRef.current;
        let accountRemote;
        try {
          accountRemote = remote && remote.account;
        } catch (error) {
          accountRemote = undefined;
        }
        if (!accountRemote || typeof accountRemote.getState !== 'function' || typeof accountRemote.getBalance !== 'function') {
          if (mountedRef.current && seq === requestRef.current) {
            setModel({ status: 'error', message: 'remote.account is unavailable' });
          }
          return;
        }
        setModel((previous) => (previous.status === 'ready'
          ? { ...previous, refreshing: true }
          : { status: 'loading' }));
        try {
          const stateResult = await accountRemote.getState();
          if (!mountedRef.current || seq !== requestRef.current) return;
          if (!stateResult || stateResult.ok !== true) {
            throw new Error('account state: ' + failureText(stateResult));
          }
          const view = stateResult.value;
          if (!view || view.status !== 'credential-stored') {
            setModel({ status: 'signed-out' });
            return;
          }
          const balanceResult = await accountRemote.getBalance(metadata(locale));
          if (!mountedRef.current || seq !== requestRef.current) return;
          if (!balanceResult || balanceResult.ok !== true) {
            throw new Error('account balance: ' + failureText(balanceResult));
          }
          const result = balanceResult.value;
          if (!result || result.status !== 'ready') {
            setModel({ status: 'unavailable' });
            return;
          }
          setModel({
            status: 'ready',
            wallets: Array.isArray(result.value) ? result.value : [],
            bonuses: Array.isArray(result.bonusWallets) ? result.bonusWallets : [],
            updatedAt: Date.now(),
          });
        } catch (error) {
          console.error('[quota-whale] balance refresh failed', error);
          if (!mountedRef.current || seq !== requestRef.current) return;
          const message = error && error.message ? String(error.message) : 'balance refresh failed';
          setModel((previous) => (previous.status === 'ready'
            ? { ...previous, refreshing: false, stale: true }
            : { status: 'error', message }));
        }
      }, [locale, remote]);

      const activate = (event) => {
        if (suppressClickRef.current) {
          suppressClickRef.current = false;
          event.preventDefault();
          event.stopPropagation();
          return;
        }
        triggerPop();
        showPhrase();
        load();
      };

      React.useEffect(() => {
        load();
        const timer = window.setInterval(() => {
          if (!document.hidden) load();
        }, REFRESH_INTERVAL_MS);
        const onFocus = () => { load(); };
        const onVisibility = () => { if (!document.hidden) load(); };
        window.addEventListener('focus', onFocus);
        document.addEventListener('visibilitychange', onVisibility);
        return () => {
          window.clearInterval(timer);
          window.removeEventListener('focus', onFocus);
          document.removeEventListener('visibilitychange', onVisibility);
        };
      }, [load]);

      let amount = '···';
      let detail = translate('loading');
      let metric = 'loading';
      if (model.status === 'ready') {
        const wallet = Array.isArray(model.wallets) && model.wallets.length > 0 ? model.wallets[0] : null;
        amount = wallet ? money(wallet.balance, wallet.currency) : money(0, 'CNY');
        const bonus = positiveWallet(model.bonuses);
        detail = bonus ? translate('bonusLabel') + ' ' + money(bonus.balance, bonus.currency) : translate('updated');
        metric = 'ready';
      } else if (model.status === 'signed-out') {
        amount = translate('signedOut');
        detail = translate('signInHint');
        metric = 'signed-out';
      } else if (model.status === 'unavailable' || model.status === 'error') {
        amount = translate('unavailable');
        detail = translate('retry');
        metric = 'error';
      }

      const refreshTitle = model.status === 'error' && model.message
        ? model.message
        : translate('dragHint');

      const dragHandlers = {
        onPointerDown: beginDrag,
        onPointerMove: moveDrag,
        onPointerUp: endDrag,
        onPointerCancel: endDrag,
      };

      return h(React.Fragment, null,
        h('style', { dangerouslySetInnerHTML: { __html: CSS } }),
        h('div', {
          ref: rootRef,
          className: 'qw-root',
          'data-refreshing': model.refreshing ? 'true' : 'false',
          'data-dragging': dragging ? 'true' : 'false',
          'data-metric': metric,
          onPointerOver: handlePointerOver,
          onPointerOut: handlePointerOut,
          style: { transform: 'translate3d(' + position.x + 'px, ' + position.y + 'px, 0)' },
        },
          h('div', { className: 'qw-scale', style: { transform: 'scale(' + scale + ')' } },
            h('div', { className: 'qw-sticker' },
              h('div', {
                className: 'qw-pop',
                'data-pop': popping ? 'true' : 'false',
                onAnimationEnd: (event) => {
                  if (event.target === event.currentTarget) setPopping(false);
                },
              },
                h('img', {
                  className: 'qw-art',
                  src: MASCOT_URI,
                  alt: '',
                  draggable: false,
                }),
                h('button', Object.assign({
                  type: 'button',
                  className: 'qw-bubble',
                  title: refreshTitle,
                  onClick: activate,
                }, dragHandlers),
                  phrase
                    ? h('span', { className: 'qw-phrase', 'aria-live': 'polite' }, phrase)
                    : h(React.Fragment, null,
                      h('span', { className: 'qw-label' }, translate('label')),
                      h('span', { className: 'qw-amount', 'aria-live': 'polite' }, amount),
                      h('span', { className: 'qw-sub' }, model.stale ? translate('retry') : detail),
                    ),
                ),
                h('button', Object.assign({
                  type: 'button',
                  className: 'qw-character',
                  title: refreshTitle,
                  'aria-label': translate('refresh'),
                  onClick: activate,
                }, dragHandlers)),
              ),
            ),
          ),
        ),
      );
    }

    return {
      inject: ['slots', 'remote', 'remote.account', 'locale'],
      apply(ctx) {
        ctx.effect(() => ctx.locale.register('quota-whale', 'zh', MESSAGES.zh), 'quota-whale: zh');
        ctx.effect(() => ctx.locale.register('quota-whale', 'en', MESSAGES.en), 'quota-whale: en');
        const t = ctx.locale.bind('quota-whale');
        const locale = ctx.locale;
        const remote = ctx.remote;
        function Widget() {
          return h(QuotaWhale, { t, locale, remote });
        }
        ctx.slots.inject('shell.overlay', () => ctx.slots.register({
          name: 'shell.overlay',
          id: 'quota-whale',
          order: 20,
        }, Widget));
      },
    };
  },
});
